style.css:
@-moz-document domain("youtube.com") {
/* Target the main page wrapper to add the background image */
    body, html, #content {
        background-image: url("https://i.pinimg.com/736x/09/e5/21/09e521b974977d5b7a1fa043ed2a1c1b.jpg") !important;
        background-size: cover !important;
        background-attachment: fixed !important;
        background-position: center !important;
        background-repeat: no-repeat !important;
    }
    
    /* Make YouTube's default background transparent so your image shows */
    ytd-app {
        background: transparent !important;
    }
}
